use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH}};
pub fn write_csv(kind:&str,no:&str,content:&str)->std::io::Result<PathBuf>{let d=PathBuf::from(r"C:\Fatura");fs::create_dir_all(&d)?;let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap();let secs=now.as_secs();let dt=chrono::DateTime::<chrono::Local>::from(UNIX_EPOCH+std::time::Duration::from_secs(secs));let ts=format!("{}{:03}",dt.format("%Y%m%d%H%M%S"),now.subsec_millis());let f=d.join(format!("{}_{}_{}.csv",kind,no,ts));let t=PathBuf::from(format!("{}.tmp",f.display()));fs::write(&t,content.as_bytes())?;fs::rename(&t,&f)?;Ok(f)}
